// Normalize each article: clean URL (strip tracking params), build hash, keep fields we need
const items = $input.all();
const out = [];
for (const item of items) {
  const j = item.json || {};
  const rawTitle = (j.title || '').toString().trim();
  const rawLink = (j.link || '').toString().trim();
  const rawDesc = (j.description || '').toString().trim();
  if (!rawTitle || !rawLink) continue;

  // Strip query params + trailing slash for stable matching
  let cleanUrl = rawLink;
  try {
    const u = new URL(rawLink);
    u.search = '';
    u.hash = '';
    cleanUrl = u.toString().replace(/\/$/, '').toLowerCase();
  } catch (e) {
    cleanUrl = rawLink.toLowerCase();
  }

  // Title-based fallback hash (Google News rewrites URLs sometimes)
  const titleKey = rawTitle.toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim().slice(0, 120);

  out.push({
    json: {
      title: rawTitle,
      url: rawLink,
      clean_url: cleanUrl,
      title_key: titleKey,
      description: rawDesc.slice(0, 500),
      pubDate: j.pubDate || ''
    }
  });
}
return out;

// Dedupe within today's pull (by clean_url and title_key)
const all = $input.first().json.data || [];
const seenUrl = new Set();
const seenTitle = new Set();
const unique = [];
for (const a of all) {
  if (seenUrl.has(a.clean_url) || seenTitle.has(a.title_key)) continue;
  seenUrl.add(a.clean_url);
  seenTitle.add(a.title_key);
  unique.push(a);
}
// Cap at 20 to keep downstream cheap
return unique.slice(0, 20).map(a => ({ json: a }));

// Build a Set of already-sent clean_urls and title_keys from Notion history.
// Then filter today's candidate articles against that set.
// If history fetch returned nothing, treat it as empty (first run case).

let history = [];
try {
  history = $('Get Sent History').all() || [];
} catch (e) {
  history = [];
}

const sentUrls = new Set();
const sentTitles = new Set();
const recentTopics = [];

for (const h of history) {
  const props = (h.json && h.json.properties) || {};
  // Defensive: Notion property shapes vary. Read both rich_text and title arrays.
  const cu = props['Clean URL'];
  const tk = props['Title Key'];
  const tt = props['Title'];

  const readText = (prop) => {
    if (!prop) return '';
    const arr = prop.rich_text || prop.title || [];
    return arr.map(x => x.plain_text || '').join('').toLowerCase().trim();
  };

  const cuVal = readText(cu);
  const tkVal = readText(tk);
  const ttVal = readText(tt);

  if (cuVal) sentUrls.add(cuVal);
  if (tkVal) sentTitles.add(tkVal);
  if (ttVal) recentTopics.push(ttVal);
}

const candidates = $('Dedupe Today\'s Pull').all().map(i => i.json);
const fresh = candidates.filter(c =>
  !sentUrls.has(c.clean_url) && !sentTitles.has(c.title_key)
);

// Output a single item carrying the fresh list + recent topics (for the LLM to diversify against)
return [{
  json: {
    fresh_count: fresh.length,
    fresh_articles: fresh,
    recent_topics: recentTopics.slice(0, 20)
  }
}];

