// Parse Gemini's pick. Strip code fences if it ignored instructions.
const raw = ($input.first().json.content && $input.first().json.content.parts && $input.first().json.content.parts[0] && $input.first().json.content.parts[0].text) || '';
let clean = raw.trim();
clean = clean.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();

let pick;
try {
  pick = JSON.parse(clean);
} catch (e) {
  // Fallback: pick the first fresh article
  const fresh = $('Filter Out Already Sent').first().json.fresh_articles || [];
  if (fresh.length === 0) {
    throw new Error('No fresh articles and Gemini pick failed to parse: ' + raw);
  }
  pick = {
    index: 0,
    title: fresh[0].title,
    url: fresh[0].url,
    clean_url: fresh[0].clean_url,
    title_key: fresh[0].title_key,
    reason: 'fallback: gemini pick failed to parse'
  };
}

// Cross-reference back to the fresh list to grab description (Gemini doesn't echo it).
const fresh = $('Filter Out Already Sent').first().json.fresh_articles || [];
const matched = fresh.find(a => a.clean_url === pick.clean_url) || fresh[pick.index] || fresh[0];

return [{
  json: {
    title: pick.title || matched.title,
    url: pick.url || matched.url,
    clean_url: pick.clean_url || matched.clean_url,
    title_key: pick.title_key || matched.title_key,
    description: matched.description || '',
    reason: pick.reason || ''
  }
}];

