let parsed;
try {
  parsed = JSON.parse(clean);
} catch (e) {
  // Fallback if Gemini ignores JSON instruction
  parsed = { subject: 'New angle', body: raw };
}

const today = new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short' });
return [{
  json: {
    subject: `LI Draft [${today}] — ${parsed.subject}`,
    body: parsed.body
